package com.example

import com.example.ExamQuestionHelper.QSpec

/**
 * Domain 1: පෘථිවි චලිත, අක්ෂාංශ-දේශාංශ හා වේලා කලාප
 * (Earth Rotation & Revolution, Seasons, Latitudes, Valid Longitudes 0°-180°, Real World Time Zones & Isolines)
 * Strictly unique, geographically valid, non-repetitive MCQs.
 */
internal object GeographyLiveExamEarthTimeBank {

  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun earthAndTimeQuestions(): List<QSpec> {
    val t = "පෘථිවි චලිත, අක්ෂාංශ-දේශාංශ හා වේලා කලාප"
    return listOf(
      q(t, "පෘථිවිය තම අක්ෂය වටා බටහිර සිට නැගෙනහිර දෙසට එක් සම්පූර්ණ වටයක් භ්‍රමණය වීමට ගතවන නිශ්චිත කාලය කොපමණද?",
        "පැය 23 විනාඩි 56 තත්පර 4 (ආසන්නව පැය 24)", "පැය 12", "දින 365", "දින 29",
        "පෘථිවි භ්‍රමණය හේතුවෙන් දිවා රාත්‍රී ඇතිවන අතර සාමාන්‍ය සූර්ය දිනයක් පැය 24 ක් ලෙස සැලකේ."),
      q(t, "පෘථිවියේ අක්ෂය එහි කක්ෂ තලයේ ලම්බකයට අංශක කීයක ආනතියකින් ඇලව පවතීද?",
        "23.5° (අංශක 23 කලා 30)", "45°", "66.5°", "90°",
        "අක්ෂයේ 23.5° ආනතිය හා පරිභ්‍රමණය නිසා සෘතු භේදය සහ දිවා රාත්‍රී කාල වෙනස ඇතිවේ."),
      q(t, "පෘථිවි භ්‍රමණය නිසා සුළං සහ සාගර ධාරා උතුරු අර්ධගෝලයේදී දකුණු පසටත්, දකුණු අර්ධගෝලයේදී වම් පසටත් හැරවීමේ ආචරණය කුමක්ද?",
        "කෝරියෝලිස් ආචරණය (Coriolis Effect / Ferrel's Law)", "හරිතාගාර ආචරණය", "උදම් බලය", "ගුරුත්වාකර්ෂණය",
        "පෘථිවිය බටහිර සිට නැගෙනහිරට කැරකීම නිසා චලනය වන වායු හා ජල ධාරා අපගමනය වේ."),
      q(t, "ශ්‍රී ලංකාවේ සම්මත වේලාව ග්‍රිනිච් මධ්‍යන්‍ය වේලාවට (UTC/GMT) වඩා කොපමණ ඉදිරියෙන් පවතීද?",
        "පැය 5 විනාඩි 30 ක් (+05:30)", "පැය 6 ක් (+06:00)", "පැය 4 විනාඩි 30 ක්", "පැය 5 විනාඩි 30 ක් පසුපසින්",
        "ශ්‍රී ලංකාව ඉන්දියානු සම්මත වේලාවට සමානව නැගෙනහිර දේශාංශ 82°30'E මත පදනම්ව UTC +5:30 භාවිත කරයි."),
      q(t, "ලන්ඩන් නුවර (0°) උදෑසන 8.00 වන විට ශ්‍රී ලංකාවේ (UTC +5:30) වේලාව කීයද?",
        "ප.ව. 1.30 (13:30)", "පෙ.ව. 2.30", "ප.ව. 3.30", "පෙ.ව. 11.30",
        "ශ්‍රී ලංකාව GMT ට වඩා පැය 5 විනාඩි 30 ක් ඉදිරියෙන් සිටින බැවින් 8.00 + 5.30 = ප.ව. 1.30 වේ."),
      q(t, "පෘථිවිය සිය අක්ෂය වටා පැය 1 කදී භ්‍රමණය වන දේශාංශ ප්‍රමාණය අංශක කීයද?",
        "15°", "1°", "30°", "4°",
        "සම්පූර්ණ වටය 360° / පැය 24 = පැයකට 15° බැගින් භ්‍රමණය වේ."),
      q(t, "දේශාංශ 1° ක් හරහා හිරු ගමන් කිරීමට (හෙවත් පෘථිවිය භ්‍රමණය වීමට) ගතවන කාලය මිනිත්තු කීයද?",
        "විනාඩි 4 කි", "විනාඩි 15 කි", "විනාඩි 60 කි", "විනාඩි 1 කි",
        "පැය 1 (විනාඩි 60) / 15° = අංශක 1 කට විනාඩි 4 කි."),
      q(t, "පෘථිවිය මත භූගෝලීය දේශාංශ පිහිටුම්වල උපරිම අගය නැගෙනහිරට හෝ බටහිරට විහිදෙන සීමාව කුමක්ද?",
        "0° සිට 180° දක්වා", "0° සිට 360° දක්වා", "0° සිට 90° දක්වා", "0° සිට 300° දක්වා",
        "ග්‍රිනිච් මධ්‍ය රේඛාව (0°) සිට නැගෙනහිරට 180°E දක්වාත් බටහිරට 180°W දක්වාත් දේශාංශ මනිනු ලැබේ."),
      q(t, "උතුරු හා දකුණු අක්ෂාංශ මැනීමේ උපරිම සීමාව සමකයේ සිට ධ්‍රැව දක්වා අංශක කීයද?",
        "0° සිට 90° දක්වා", "0° සිට 180° දක්වා", "0° සිට 45° දක්වා", "0° සිට 360° දක්වා",
        "සමකය 0° වන අතර උත්තර ධ්‍රැවය 90°N හා දක්ෂිණ ධ්‍රැවය 90°S වේ."),
      q(t, "ගුවන් යානයක් ජපානයේ සිට පැසිෆික් සාගරය හරහා නැගෙනහිර දෙසට ගමන් කරමින් අන්තර්ජාතික දින රේඛාව (180°) පසු කළහොත් කැලැන්ඩරයේ දිනයට සිදුවන්නේ කුමක්ද?",
        "දිනයක් අඩු වේ (එකම දිනය දෙවරක් ගත කිරීමට සිදුවේ)", "දිනයක් වැඩි වේ", "වේලාව පමණක් වෙනස් වේ", "කිසිදු වෙනසක් නොවේ",
        "බටහිර සිට නැගෙනහිරට (ආසියාවේ සිට ඇමරිකාවට) 180° රේඛාව පසු කිරීමේදී දිනයක් ආපසු යයි."),
      q(t, "නවසීලන්තයේ සිට බටහිරට පියාසර නොකර, ඇමරිකාවේ සිට බටහිර දෙසට (ජපානය දෙසට) 180° අන්තර්ජාතික දින රේඛාව පසු කරන නැවක දිනය වෙනස් වන්නේ කෙසේද?",
        "දිනයක් ඉදිරියට යයි (එක් දිනක් මඟ හැරේ)", "දිනයක් ආපසු යයි", "සතියක් වෙනස් වේ", "වේලාව නවතී",
        "නැගෙනහිර සිට බටහිරට දින රේඛාව තරණය කරන විට දිනයක් එකතු වේ (උදා: සඳුදා සිට අඟහරුවාදාට)."),
      q(t, "අන්තර්ජාතික දින රේඛාව (180° දේශාංශය) බේරිං සමුද්‍ර සන්ධිය හා පැසිෆික් දූපත් අසලදී සෘජු රේඛාවක් නොවී වංගු සහිතව ඇඳ තිබෙන්නේ ඇයි?",
        "එකම රටකට හෝ දූපත් සමූහයකට දින දෙකක් ඇතිවීම වැළැක්වීමට", "නැව් ගමනාගමනය නැවැත්වීමට", "උණුසුම අඩු කිරීමට", "චුම්බක ධ්‍රැවය මඟහැරීමට",
        "සයිබීරියාව, ඇලූෂියන් දූපත් හා ෆීජි-කිරිබාටි දූපත් එකම දිනයේ තබා ගැනීමට රේඛාව නමා ඇත."),
      q(t, "ජූනි 21 වන දින සූර්යයා සෘජුවම මුදුන් වන අක්ෂාංශ රේඛාව කුමක්ද?",
        "කර්කටක නිවර්තනය (23.5° N)", "මකර නිවර්තනය (23.5° S)", "සමකය (0°)", "ආක්ටික් වෘත්තය (66.5° N)",
        "ජූනි 21 උත්තර අයනයේදී (Summer Solstice) උතුරු අර්ධගෝලයේ දිගම දිවා කාලය ඇතිවේ."),
      q(t, "දෙසැම්බර් 22 වන දින සූර්යයා සෘජුවම ලම්බකව බබළන ප්‍රධාන අක්ෂාංශ රේඛාව කුමක්ද?",
        "මකර නිවර්තනය (23.5° S)", "කර්කටක නිවර්තනය (23.5° N)", "සමකය (0°)", "ඇන්ටාක්ටික් වෘත්තය (66.5° S)",
        "දෙසැම්බර් 22 දක්ෂිණ අයනයේදී (Winter Solstice) දකුණු අර්ධගෝලයට ගිම්හානය හා දිගම දිවා කාලය ලැබේ."),
      q(t, "මාර්තු 21 සහ සැප්තැම්බර් 23 යන දිනවලදී මුළු ලෝකයේම දිවා සහ රාත්‍රී කාලය පැය 12 බැගින් සමාන වන්නේ ඇයි?",
        "සූර්යයා සෘජුවම සමකය (0°) මත මුදුන් වන බැවින් (විෂුව දින)", "පෘථිවිය භ්‍රමණය නවතින බැවින්", "සඳු පෘථිවිය ආවරණය කරන බැවින්", "ධ්‍රැව දෙක එකතු වන බැවින්",
